import json

def gera_relatorio(caminho):
    try:
        pedidos = json.load(open(caminho))
    except:
        return {}
    soma = 0
    for p in pedidos:
        soma += p["total"]
    return {"qtd": len(pedidos), "soma": soma, "media": soma / len(pedidos)}

