import pytest

from fretes.frete import calcula_frete

def test_sp():
    assert calcula_frete("SP", 1) == 12.0


def test_desconto_zero_explicito():
    assert calcula_frete("SP", 1, desconto_pct=0) == 12.0


def test_desconto_dez_por_cento():
    assert calcula_frete("SP", 1, desconto_pct=10) == 10.8


