    assert calcula_frete("RJ", 3, desconto_pct=100) == 0.0


def test_desconto_fracionado_arredonda():
    # RJ, 1 kg: 14.5 * 0.875 = 12.6875
    assert calcula_frete("RJ", 1, desconto_pct=12.5) == 12.69


